"""Textos legales ES/EN del sitio (borradores a completar y revisar por un profesional).
Marco: RGPD (UE) 2016/679, LOPDGDD (LO 3/2018), LSSI-CE (Ley 34/2002) y guía de cookies de la AEPD.
Los datos del titular son [PENDIENTE]: no se inventan."""

PEND_ES, PEND_EN = "[PENDIENTE]", "[PENDING]"

def doc(kind, lang, ctx):
    es = lang == "es"
    L = lambda a, b: a if es else b
    P = PEND_ES if es else PEND_EN
    NAME, DOMAIN, UPD = ctx["NAME"], ctx["DOMAIN"], ctx["UPDATED"][lang]
    u = ctx["u"]
    owner = L(f"{P} (nombre y apellidos o razón social)", f"{P} (full name or company name)")
    ident = L(f"Titular: {owner}; NIF/CIF: {P}; domicilio: {P}; correo electrónico de contacto: {P}; datos de inscripción registral, si procede: {P}.",
              f"Owner: {owner}; tax ID: {P}; address: {P}; contact email: {P}; commercial registry details, if applicable: {P}.")
    contact = L(f"a {P} (correo electrónico del titular)", f"to {P} (the owner's email address)")
    links = lambda k, es_t, en_t: f'<a href="{u(k, lang)}">{L(es_t, en_t)}</a>'

    if kind == "legal":
        h1 = L("Aviso legal", "Legal notice")
        secs = [
         (L("1. Información del titular", "1. Site owner information"),
          f"<p>{L('En cumplimiento del artículo 10 de la Ley 34/2002, de Servicios de la Sociedad de la Información y de Comercio Electrónico (LSSI-CE), se informa de los datos del titular de este sitio web:', 'In accordance with Article 10 of Spanish Law 34/2002 on Information Society Services and Electronic Commerce (LSSI-CE), the owner of this website is identified as follows:')}</p><p>{ident}</p><p>{L('Sitio web', 'Website')}: {DOMAIN}</p>"),
         (L("2. Objeto", "2. Purpose"),
          f"<p>{L(f'Este sitio presenta la trayectoria profesional de {NAME}, sus ideas sobre negocios, liderazgo y real estate, y facilita el contacto profesional. Su contenido es informativo.', f'This website presents the professional background of {NAME}, his ideas on business, leadership and real estate, and makes professional contact easier. Its content is informational.')}</p>"),
         (L("3. Condiciones de uso", "3. Terms of use"),
          f"<p>{L('El acceso y uso del sitio se rigen por los', 'Access to and use of the site are governed by the')} {links('terms', 'Términos y condiciones', 'Terms and conditions')}.</p>"),
         (L("4. Propiedad intelectual e industrial", "4. Intellectual and industrial property"),
          f"<p>{L('Los textos, imágenes, diseño y demás contenidos del sitio pertenecen al titular o se utilizan con autorización, y están protegidos por la normativa de propiedad intelectual. Queda prohibida su reproducción, distribución o transformación sin autorización, salvo cita breve con atribución y enlace.', 'The texts, images, design and other content of the site belong to the owner or are used with permission, and are protected by intellectual property law. Reproduction, distribution or transformation without permission is prohibited, except for brief quotation with attribution and a link.')}</p><p>{L('Los nombres y marcas de terceras empresas (por ejemplo eXp Realty, Hauzz, Rive, Kodit, Tiko o Pensam) pertenecen a sus respectivos titulares y se mencionan únicamente para describir la trayectoria profesional, sin que impliquen patrocinio, aval ni relación oficial con esas empresas.', 'The names and trademarks of third-party companies (for example eXp Realty, Hauzz, Rive, Kodit, Tiko or Pensam) belong to their respective owners and are mentioned only to describe professional background, without implying sponsorship, endorsement or any official relationship with those companies.')}</p>"),
         (L("5. Responsabilidad y enlaces", "5. Liability and links"),
          f"<p>{L('El titular procura que la información sea exacta y esté actualizada, sin garantizar que esté libre de errores. No se responsabiliza de los contenidos de sitios de terceros enlazados, que se rigen por sus propias condiciones y políticas.', 'The owner makes every effort to keep the information accurate and up to date, without guaranteeing that it is error-free. The owner is not responsible for the content of linked third-party sites, which are governed by their own terms and policies.')}</p>"),
         (L("6. Protección de datos y cookies", "6. Data protection and cookies"),
          f"<p>{L('Consulta la', 'See the')} {links('privacy', 'Política de privacidad', 'Privacy policy')} {L('y la', 'and the')} {links('cookies', 'Política de cookies', 'Cookie policy')}.</p>"),
         (L("7. Legislación aplicable y jurisdicción", "7. Governing law and jurisdiction"),
          f"<p>{L(f'Este aviso se rige por la legislación española. Para cualquier controversia, y salvo que la ley establezca otro fuero imperativo (en particular para consumidores y usuarios, que podrán acudir a los tribunales de su domicilio), las partes se someten a los juzgados y tribunales de {P} (localidad del titular).', f'This notice is governed by Spanish law. For any dispute, and unless the law sets a mandatory forum (in particular for consumers, who may go to the courts of their place of residence), the parties submit to the courts of {P} (owner locality).')}</p>"),
        ]
    elif kind == "terms":
        h1 = L("Términos y condiciones de uso", "Terms and conditions of use")
        secs = [
         (L("1. Aceptación", "1. Acceptance"),
          f"<p>{L('El acceso y uso de este sitio atribuye la condición de usuario e implica la aceptación de estos términos. Si no estás de acuerdo, no uses el sitio.', 'Accessing and using this site makes you a user and implies acceptance of these terms. If you do not agree, please do not use the site.')}</p>"),
         (L("2. Uso permitido", "2. Permitted use"),
          f"<p>{L('Te comprometes a usar el sitio de forma lícita, de buena fe y sin dañar su funcionamiento, los derechos de terceros ni la imagen del titular. Se prohíbe el uso automatizado masivo (scraping abusivo), la suplantación de identidad y cualquier acción que comprometa la seguridad del sitio.', 'You agree to use the site lawfully, in good faith and without harming its operation, the rights of third parties or the owner’s reputation. Abusive automated use (scraping), impersonation and any action that compromises the security of the site are prohibited.')}</p>"),
         (L("3. Contenido informativo", "3. Informational content"),
          f"<p>{L('Los contenidos son informativos y reflejan la experiencia y opiniones del titular. No constituyen asesoramiento financiero, de inversión, legal, fiscal ni profesional de ningún tipo, ni una oferta o recomendación de contratar o invertir. Las cifras y resultados se presentan en el contexto indicado, y los resultados pasados no garantizan resultados futuros.', 'The content is informational and reflects the owner’s experience and opinions. It does not constitute financial, investment, legal, tax or any other professional advice, nor an offer or recommendation to hire or invest. Figures and results are presented in the context indicated, and past results do not guarantee future results.')}</p>"),
         (L("4. Comunicaciones de contacto", "4. Contact communications"),
          f"<p>{L('El formulario de contacto permite enviar un mensaje al titular. Enviarlo no implica obligación de respuesta ni crea relación profesional alguna. Se prohíbe el uso del formulario para enviar publicidad no solicitada, contenido ilícito o intentos de acceso no autorizado.', 'The contact form lets you send a message to the owner. Sending it does not create an obligation to reply or any professional relationship. Using the form to send unsolicited advertising, unlawful content or unauthorised access attempts is prohibited.')}</p>"),
         (L("5. Propiedad intelectual", "5. Intellectual property"),
          f"<p>{L('Rige lo dispuesto en el', 'The provisions of the')} {links('legal', 'Aviso legal', 'Legal notice')}.</p>"),
         (L("6. Enlaces y servicios de terceros", "6. Third-party links and services"),
          f"<p>{L('El sitio puede enlazar a páginas o servicios de terceros. El titular no controla ni responde de su contenido, disponibilidad ni políticas.', 'The site may link to third-party pages or services. The owner does not control and is not responsible for their content, availability or policies.')}</p>"),
         (L("7. Disponibilidad y limitación de responsabilidad", "7. Availability and limitation of liability"),
          f"<p>{L('El sitio se ofrece «tal cual». El titular no garantiza su disponibilidad continuada ni la ausencia de errores. En la medida permitida por la ley, no responde de daños derivados del uso del sitio o de la imposibilidad de usarlo, sin excluir aquella responsabilidad que la normativa no permita excluir.', 'The site is provided “as is”. The owner does not guarantee continuous availability or the absence of errors. To the extent permitted by law, the owner is not liable for damages arising from use of the site or inability to use it, without excluding any liability that cannot be excluded by law.')}</p>"),
         (L("8. Modificaciones", "8. Changes"),
          f"<p>{L('El titular puede modificar estos términos y el contenido del sitio en cualquier momento. La versión vigente es la publicada en esta página.', 'The owner may modify these terms and the content of the site at any time. The version in force is the one published on this page.')}</p>"),
         (L("9. Legislación y jurisdicción", "9. Governing law and jurisdiction"),
          f"<p>{L('Estos términos se rigen por la legislación española. Los consumidores y usuarios conservan los derechos que la normativa les reconoce, incluido acudir a los tribunales de su domicilio. Titular y datos de contacto: ver el', 'These terms are governed by Spanish law. Consumers keep the rights the law grants them, including the right to go to the courts of their place of residence. Owner and contact details: see the')} {links('legal', 'Aviso legal', 'Legal notice')}.</p>"),
        ]
    elif kind == "privacy":
        h1 = L("Política de privacidad", "Privacy policy")
        secs = [
         (L("1. Responsable del tratamiento", "1. Data controller"),
          f"<p>{L('Conforme al Reglamento (UE) 2016/679 (RGPD) y a la Ley Orgánica 3/2018 (LOPDGDD), el responsable del tratamiento de tus datos es:', 'Under Regulation (EU) 2016/679 (GDPR) and Spanish Organic Law 3/2018 (LOPDGDD), the controller of your personal data is:')}</p><p>{ident}</p><p>{L('Delegado de protección de datos: no designado, al no ser obligatorio.', 'Data protection officer: not appointed, as it is not mandatory.')} {P}: {L('confirmar.', 'confirm.')}</p>"),
         (L("2. Qué datos tratamos y de dónde proceden", "2. What data we process and where it comes from"),
          f"<ul><li><b>{L('Datos técnicos de navegación', 'Technical browsing data')}:</b> {L('al visitar el sitio, el proveedor de alojamiento puede registrar tu dirección IP, fecha y hora, página solicitada y datos del navegador (registros de servidor) por motivos de seguridad y funcionamiento. Proveedor:', 'when you visit the site, the hosting provider may log your IP address, date and time, page requested and browser data (server logs) for security and operational reasons. Provider:')} {P}.</li><li><b>{L('Datos del formulario de contacto', 'Contact form data')}:</b> {L('si usas el formulario, tratamos el nombre, el correo electrónico, la empresa u organización (opcional), el motivo de contacto y el mensaje que facilites. Se envían a un buzón privado de correo electrónico y esta web no los almacena.', 'if you use the form, we process the name, email address, company or organisation (optional), reason for contact and the message you provide. They are sent to a private mailbox and this website does not store them.')}</li><li><b>{L('Preferencias de cookies', 'Cookie preferences')}:</b> {L('se guardan únicamente en tu dispositivo (ver la', 'stored only on your device (see the')} {links('cookies', 'Política de cookies', 'Cookie policy')}).</li></ul>"),
         (L("3. Finalidades y base jurídica", "3. Purposes and legal basis"),
          f"<ul><li>{L('Atender tu consulta o propuesta de contacto: tu consentimiento al enviar el formulario (art. 6.1.a RGPD) y, en su caso, medidas precontractuales a petición tuya (art. 6.1.b RGPD).', 'Handling your enquiry or contact proposal: your consent when you submit the form (Art. 6.1.a GDPR) and, where applicable, pre-contractual measures at your request (Art. 6.1.b GDPR).')}</li><li>{L('Seguridad y correcto funcionamiento del sitio: interés legítimo (art. 6.1.f RGPD).', 'Security and proper operation of the site: legitimate interest (Art. 6.1.f GDPR).')}</li><li>{L('Recordar tus preferencias de cookies: cumplimiento de una obligación legal (art. 6.1.c RGPD y art. 22.2 LSSI-CE).', 'Remembering your cookie preferences: compliance with a legal obligation (Art. 6.1.c GDPR and Art. 22.2 LSSI-CE).')}</li><li>{L('Analítica del sitio, si se activa en el futuro: únicamente con tu consentimiento (art. 6.1.a RGPD), que puedes retirar en cualquier momento.', 'Site analytics, if enabled in the future: only with your consent (Art. 6.1.a GDPR), which you can withdraw at any time.')}</li></ul><p>{L('No se toman decisiones automatizadas ni se elaboran perfiles con tus datos.', 'No automated decision-making or profiling is carried out with your data.')}</p>"),
         (L("4. Destinatarios", "4. Recipients"),
          f"<p>{L('Tus datos no se ceden a terceros salvo obligación legal. Pueden acceder a ellos, como encargados o proveedores del servicio: el proveedor de alojamiento del sitio (Cloudflare)', 'Your data is not disclosed to third parties except where legally required. The following may access it as processors or service providers: the site’s hosting provider')} ({P}), {L('Google (carga de tipografías, mientras no se alojen en el propio sitio) y el proveedor de envío de correo del formulario ({P}), que se rigen por sus propias políticas.', 'Google (font loading, until fonts are hosted on the site itself) and the email delivery provider used by the form ({P}), which are governed by their own policies.')}</p>"),
         (L("5. Transferencias internacionales", "5. International transfers"),
          f"<p>{L('Algunos de esos proveedores pueden estar ubicados en Estados Unidos. En tal caso, la transferencia se ampara en la decisión de adecuación del Marco de Privacidad de Datos UE–EE. UU. o en cláusulas contractuales tipo de la Comisión Europea.', 'Some of those providers may be located in the United States. In that case, the transfer relies on the adequacy decision for the EU–US Data Privacy Framework or on the European Commission’s standard contractual clauses.')} {P}: {L('confirmar proveedores finales.', 'confirm final providers.')}</p>"),
         (L("6. Plazo de conservación", "6. Retention period"),
          f"<p>{L('Las consultas se conservan el tiempo necesario para atenderlas y, después, bloqueadas durante los plazos de prescripción de posibles responsabilidades. Los registros técnicos, según la política del proveedor de alojamiento', 'Enquiries are kept for as long as needed to handle them and then blocked for the limitation periods of possible liabilities. Technical logs, per the hosting provider’s policy')} ({P}). {L('Las preferencias de cookies se conservan 12 meses.', 'Cookie preferences are kept for 12 months.')}</p>"),
         (L("7. Tus derechos", "7. Your rights"),
          f"<p>{L('Puedes ejercer los derechos de acceso, rectificación, supresión, oposición, limitación del tratamiento y portabilidad, así como retirar tu consentimiento en cualquier momento (sin afectar a la licitud del tratamiento previo), escribiendo', 'You may exercise your rights of access, rectification, erasure, objection, restriction of processing and portability, and withdraw your consent at any time (without affecting the lawfulness of prior processing), by writing')} {contact}, {L('indicando el derecho que ejerces y acreditando tu identidad.', 'stating the right you wish to exercise and proving your identity.')}</p><p>{L('Si consideras que tus derechos no han sido atendidos, puedes presentar una reclamación ante la Agencia Española de Protección de Datos (www.aepd.es) o ante la autoridad de control de tu país de residencia.', 'If you believe your rights have not been respected, you may lodge a complaint with the Spanish Data Protection Agency (www.aepd.es) or with the supervisory authority of your country of residence.')}</p>"),
         (L("8. Menores de edad", "8. Minors"),
          f"<p>{L('Este sitio no está dirigido a menores de 14 años. Si crees que un menor ha facilitado datos, contacta con el titular para su supresión.', 'This site is not aimed at children under 14. If you believe a minor has provided data, contact the owner so it can be deleted.')}</p>"),
         (L("9. Seguridad", "9. Security"),
          f"<p>{L('El sitio se sirve por HTTPS y aplica cabeceras de seguridad y una política de seguridad de contenido restrictiva. Se adoptan medidas técnicas y organizativas razonables para proteger los datos.', 'The site is served over HTTPS and applies security headers and a restrictive content security policy. Reasonable technical and organisational measures are taken to protect data.')}</p>"),
         (L("10. Cambios en esta política", "10. Changes to this policy"),
          f"<p>{L('Esta política puede actualizarse para reflejar cambios legales o del sitio. La versión vigente es la publicada aquí, con su fecha.', 'This policy may be updated to reflect legal or site changes. The version in force is the one published here, with its date.')}</p>"),
        ]
    else:  # cookies
        h1 = L("Política de cookies", "Cookie policy")
        tb = lambda rows: "<div class='tbl'><table><thead><tr>" + "".join(f"<th>{c}</th>" for c in (L("Nombre / recurso", "Name / resource"), L("Titular", "Provider"), L("Finalidad", "Purpose"), L("Duración", "Duration"), L("Tipo", "Type"))) + "</tr></thead><tbody>" + "".join("<tr>" + "".join(f"<td>{c}</td>" for c in r) + "</tr>" for r in rows) + "</tbody></table></div>"
        secs = [
         (L("1. Qué son las cookies y tecnologías similares", "1. What cookies and similar technologies are"),
          f"<p>{L('Las cookies son pequeños archivos que un sitio web guarda en tu dispositivo. Esta política también cubre tecnologías similares, como el almacenamiento local del navegador (localStorage). Se rigen por el artículo 22.2 de la LSSI-CE y por el RGPD.', 'Cookies are small files that a website stores on your device. This policy also covers similar technologies, such as browser local storage (localStorage). They are governed by Article 22.2 of the LSSI-CE and the GDPR.')}</p>"),
         (L("2. Qué usa este sitio", "2. What this site uses"),
          tb([("jab-consent (localStorage)", L("Propio", "First-party"), L("Recordar tu elección sobre cookies", "Remember your cookie choice"), L("12 meses", "12 months"), L("Técnica (necesaria)", "Technical (necessary)")),
              ("fonts.googleapis.com / fonts.gstatic.com", "Google", L("Carga de las tipografías del sitio. Tu navegador envía tu dirección IP a Google; según su documentación, no instala cookies.", "Loading of the site’s typefaces. Your browser sends your IP address to Google; according to its documentation it does not set cookies."), L("Solo durante la carga", "Only while loading"), L("Recurso de terceros (se sustituirá por alojamiento propio)", "Third-party resource (to be replaced by self-hosting)")),
              (L("Analítica", "Analytics"), "—", L("Actualmente no se utiliza ninguna herramienta de analítica.", "No analytics tool is currently used."), "—", L("Solo con tu consentimiento, si se añade", "Only with your consent, if added"))]) + f"<p>{L('No se utilizan cookies publicitarias ni de seguimiento entre sitios.', 'No advertising or cross-site tracking cookies are used.')}</p>"),
         (L("3. Categorías", "3. Categories"),
          f"<ul><li><b>{L('Técnicas o necesarias', 'Technical or necessary')}:</b> {L('permiten el funcionamiento del sitio y recordar tu elección. Están exentas de consentimiento.', 'allow the site to work and remember your choice. They are exempt from consent.')}</li><li><b>{L('Analíticas', 'Analytics')}:</b> {L('miden el uso del sitio para mejorarlo. Requieren tu consentimiento y están desactivadas por defecto.', 'measure the use of the site to improve it. They require your consent and are off by default.')}</li></ul>"),
         (L("4. Cómo gestionar tu consentimiento", "4. How to manage your consent"),
          f"<p>{L('Puedes aceptar, rechazar o configurar las cookies no necesarias en el aviso inferior, con la misma facilidad con la que las aceptas. Puedes cambiar o retirar tu elección en cualquier momento:', 'You can accept, reject or configure non-necessary cookies in the bottom notice, as easily as you accept them. You can change or withdraw your choice at any time:')}</p><p><button type='button' class='btn' data-consent-open>{L('Cambiar mis preferencias de cookies', 'Change my cookie preferences')}</button></p><p>{L('También puedes bloquear o eliminar cookies desde la configuración de tu navegador (Chrome, Firefox, Safari, Edge u otro). Ten en cuenta que bloquear las necesarias puede afectar al funcionamiento del sitio.', 'You can also block or delete cookies from your browser settings (Chrome, Firefox, Safari, Edge or other). Blocking necessary ones may affect how the site works.')}</p>"),
         (L("5. Renovación del consentimiento", "5. Consent renewal"),
          f"<p>{L('Tu elección se conserva 12 meses; pasado ese plazo, o si cambian las cookies usadas, volveremos a preguntarte.', 'Your choice is kept for 12 months; after that, or if the cookies used change, we will ask you again.')}</p>"),
         (L("6. Más información y titular", "6. More information and owner"),
          f"<p>{L('Titular y datos de contacto: ver el', 'Owner and contact details: see the')} {links('legal', 'Aviso legal', 'Legal notice')}. {L('Tratamiento de datos personales: ver la', 'Processing of personal data: see the')} {links('privacy', 'Política de privacidad', 'Privacy policy')}.</p>"),
        ]
    intro = L(f"Última actualización: {UPD}. Borrador pendiente de completar con los datos del titular y de revisión por un profesional del derecho antes de publicar.", f"Last updated: {UPD}. Draft pending completion with the owner’s details and review by a legal professional before publication.")
    body = "".join(f"<h2>{a}</h2>{b}" for a, b in secs)
    return h1, intro, body, [a for a, _ in secs]
